#if OPENNET_TESTING
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using NetworkHub.App;
namespace NetworkHub.Desktop;
internal static class TestsR5
{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static async Task Click(Shell shell,string name){shell.Find<CheckBox>(name).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));for(int i=0;i<200&&shell.Workspace.Switching;i++)await Task.Delay(25);Check(!shell.Workspace.Switching,"Switch did not complete");}
 internal static async Task Ui(Shell shell,AppFiles files,Func<string,Func<Task>,Task> test)
 {
  await test("R5 individual switches operate owned stubs independently of group and startup",async()=>{var saved=shell.Settings.Copy();try{await shell.StopSelected(true);var next=saved.Copy();next.ZapretSelected=false;next.TgSelected=false;next.StartupZapret=false;next.StartupTg=true;next.ConfirmStartStop=true;next.Language="ru";next.Backdrop="solid";shell.ApplySettings(next);await shell.Refresh();shell.RoutineConfirmationForTests=_=>false;shell.Find<CheckBox>("ZapretCheck").IsChecked=true;await Click(shell,"ZapretCheck");Check(!shell.Find<CheckBox>("ZapretCheck").IsChecked!.Value&&!shell.Workspace.ToolOn("zapret"),"Declined start stayed green");shell.RoutineConfirmationForTests=_=>true;shell.Find<CheckBox>("ZapretCheck").IsChecked=true;await Click(shell,"ZapretCheck");Check(shell.Workspace.ToolOn("zapret")&&!shell.Settings.ZapretSelected&&shell.Settings.StartupZapret==false,"Switch rewrote participation");int count=shell.Runtime.LaunchCount;await shell.Workspace.ToggleTool("zapret",true);Check(shell.Runtime.LaunchCount==count,"Repeated on duplicated a launch");shell.Find<CheckBox>("TgCheck").IsChecked=true;await Click(shell,"TgCheck");Check(shell.Workspace.ToolOn("tg")&&!shell.Settings.TgSelected,"TG switch selected group");shell.ShowMessage("");shell.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)shell.Window.Content,Path.Combine(files.Data,"r5-main-on.png"));shell.RoutineConfirmationForTests=_=>false;shell.Find<CheckBox>("ZapretCheck").IsChecked=false;await Click(shell,"ZapretCheck");Check(shell.Find<CheckBox>("ZapretCheck").IsChecked==true,"Declined stop stayed off");shell.RoutineConfirmationForTests=_=>true;shell.Find<CheckBox>("ZapretCheck").IsChecked=false;await Click(shell,"ZapretCheck");Check(!shell.Workspace.ToolOn("zapret")&&shell.Workspace.ToolOn("tg"),"Individual off stopped other stub");await shell.Runtime.Stop("tg",shell.Settings);await shell.Refresh();Check(shell.Find<CheckBox>("TgCheck").IsChecked==false,"Observed exit stayed green");shell.ShowMessage("");shell.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)shell.Window.Content,Path.Combine(files.Data,"r5-main-off.png"));shell.Workspace.OpenManager();var manager=shell.Window.OwnedWindows.Cast<Window>().Single(w=>w.FindName("Groupdns")!=null);((CheckBox)manager.FindName("Groupzapret")).IsChecked=true;Check(shell.Settings.ZapretSelected&&!shell.Workspace.ToolOn("zapret")&&shell.Settings.StartupZapret==false,"Group toggle launched stub or changed startup");manager.UpdateLayout();TestsR2.Capture((FrameworkElement)manager.Content,Path.Combine(files.Data,"r5-modules.png"));manager.Close();}finally{shell.RoutineConfirmationForTests=null;await shell.StopSelected(true);shell.ApplySettings(saved);}});
  await test("R5 DNS switch applies and restores a mock adapter without changing group",async()=>{var isolated=new AppFiles(Path.Combine(files.Root,"test-results/r5-dns-switch"));using var instance=new SingleInstance(isolated.Data,isolated.Log);var fake=TestsDns.Fixture(isolated.Data);var original=fake.State;DnsManagerView.ReaderForTests=fake;var preview=new Shell(isolated,true,instance);try{preview.Window.Show();preview.OpenDnsSettings();var view=(DnsManagerView)typeof(Shell).GetField("dnsWindow",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.GetValue(preview)!;view.ConfirmationForTests=_=>true;view.SelectProfile("comss");await preview.Workspace.ToggleTool("dns",true);Check(preview.DnsApplied&&preview.Find<CheckBox>("DnsCheck").IsChecked==true&&!preview.Settings.Workspace.DnsInGroup&&fake.Writes>0,"DNS switch did not apply mock independently");await preview.Workspace.ToggleTool("dns",false);Check(!preview.DnsApplied&&original.SameConfiguration(fake.State),"DNS switch did not restore original mock");view.Window.Close();}finally{preview.Dispose();preview.Window.Close();DnsManagerView.ReaderForTests=null;shell.ApplySettings(shell.Settings.Copy());}});
  await test("R5 switch start UAC failure stop failure and concurrent input use observed state",async()=>{var saved=shell.Settings.Copy();try{await shell.StopSelected(true);shell.Settings.ConfirmStartStop=false;shell.Runtime.FaultForTests=(operation,id)=>operation=="start"?new System.ComponentModel.Win32Exception(1223):null;await shell.Workspace.ToggleTool("zapret",true);Check(!shell.Workspace.ToolOn("zapret")&&shell.Find<CheckBox>("ZapretCheck").IsChecked==false,"Failed launch stayed green");shell.Runtime.FaultForTests=null;int count=shell.Runtime.LaunchCount;var first=shell.Workspace.ToggleTool("zapret",true);await shell.Workspace.ToggleTool("zapret",true);await first;Check(shell.Runtime.LaunchCount==count+1,"Concurrent switch duplicated launch");shell.Runtime.FaultForTests=(operation,id)=>operation=="stop"?new IOException("Injected stop failure"):null;await shell.Workspace.ToggleTool("zapret",false);Check(shell.Find<CheckBox>("ZapretCheck").IsChecked==true,"Failed stop stayed off");}finally{shell.Runtime.FaultForTests=null;await shell.StopSelected(true);shell.ApplySettings(saved);}});
  await test("R5 settings status repair area and pinned footer remain separated at rendered DPI",()=>{var saved=shell.Settings.Copy();try{foreach(string theme in new[]{"dark","light"})foreach(string language in new[]{"ru","en"}){var next=saved.Copy();next.Theme=theme;next.Language=language;next.Backdrop="solid";shell.ApplySettings(next);var w=shell.OpenSettings();try{w.UpdateLayout();var status=(FrameworkElement)w.FindName("StartupStatusRegion");var actions=(FrameworkElement)w.FindName("SettingsActions");Check(status.TranslatePoint(new Point(0,status.ActualHeight),w).Y+15<=actions.TranslatePoint(new Point(),w).Y,"Status touches utility buttons");foreach(double scale in new[]{1d,1.25,1.5})TestsR2.Capture((FrameworkElement)w.Content,Path.Combine(files.Data,$"r5-settings-{language}-{theme}-{scale}.png"),scale);((Button)w.FindName("SettingsAdditional")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));w.UpdateLayout();TestsR2.Capture((FrameworkElement)w.Content,Path.Combine(files.Data,$"r5-settings-expanded-{language}-{theme}.png"));}finally{w.Close();}}}finally{shell.ApplySettings(saved);}return Task.CompletedTask;});
 }
}
#endif
